UPDATE TB_ALRM_RCVR
SET ALRM_CFMTN_DT = NVL(ALRM_CFMTN_DT, SYSDATE)
WHERE ALRM_RCVR_ID = #{alrmRcvrId}
  AND RCVR_EMP_ID = #{rcvrEmpId}
  AND ALRM_DEL_YN = 'N'

UPDATE TB_ALRM_RCVR
SET ALRM_DEL_YN = 'Y',
    ALRM_DEL_DT = SYSDATE
WHERE ALRM_RCVR_ID = #{alrmRcvrId}
  AND RCVR_EMP_ID  = #{rcvrEmpId}
